<script setup lang="ts">import { computed, onMounted, ref, watch } from "vue"; import { useRoute, useRouter } from "vue-router"; import type { CategoryItem, PublishedGameSummary } from "@arcade/shared"; import { getCategories, getPortalGames } from "../services/api"; import { readFavorites, toggleFavorite, rememberRecent } from "../services/portalStorage"; import GameGrid from "../components/portal/GameGrid.vue"; import ContentStatePanel from "../components/portal/ContentStatePanel.vue"; import CategoryChipList from "../components/portal/CategoryChipList.vue";
const route = useRoute(); const router = useRouter(); const games = ref<PublishedGameSummary[]>([]); const categories = ref<CategoryItem[]>([]); const loading = ref(true); const error = ref(""); const favorites = ref<string[]>(readFavorites().values); const favoriteOnly = computed(() => route.query.favorite === "1"); const sort = computed(() => String(route.query.sort || "recommended")); const category = computed(() => String(route.query.category || ""));
async function load(): Promise<void> { loading.value = true; error.value = ""; try { const [result, categoryResult] = await Promise.all([getPortalGames({ category: category.value || undefined, sort: sort.value as "recommended" | "popular" | "newest" | "updated" }), getCategories()]); games.value = favoriteOnly.value ? result.data.filter((game) => favorites.value.includes(game.slug)) : result.data; categories.value = categoryResult; } catch { error.value = "大厅内容暂时无法加载。"; } finally { loading.value = false; } }
function setFilter(key: string, value: string): void { void router.push({ path: "/zh/games", query: value ? { ...route.query, [key]: value } : { ...route.query, [key]: undefined } }); }
function favorite(slug: string): void { favorites.value = toggleFavorite(slug).values; void load(); } function play(slug: string): void { rememberRecent(slug); void router.push(`/zh/game/${slug}/play`); } watch(() => route.fullPath, () => void load()); onMounted(() => { void load(); document.title = "游戏大厅｜星屿游廊"; });
</script><template><div class="portal-page"><section class="portal-page-heading"><span class="portal-eyebrow">GAME LIBRARY</span><h1>游戏大厅</h1><p>按品类、状态和兴趣，找到下一款想打开的游戏。</p></section><div class="catalog-toolbar"><select :value="category" aria-label="筛选分类" @change="setFilter('category', ($event.target as HTMLSelectElement).value)"><option value="">全部分类</option><option v-for="item in categories" :key="item.slug" :value="item.slug">{{ item.name }}</option></select><select :value="sort" aria-label="排序方式" @change="setFilter('sort', ($event.target as HTMLSelectElement).value)"><option value="recommended">推荐排序</option><option value="popular">热门优先</option><option value="newest">最新发布</option><option value="updated">最近更新</option></select><button class="filter-toggle" :class="{ active: favoriteOnly }" type="button" @click="setFilter('favorite', favoriteOnly ? '' : '1')">☆ 只看收藏</button></div><CategoryChipList :categories="categories" /><ContentStatePanel v-if="loading" kind="loading" title="正在加载游戏大厅" message="固定卡片尺寸，马上就好。" /><ContentStatePanel v-else-if="error" kind="error" title="游戏大厅加载失败" :message="error" action="重试" @action="load" /><ContentStatePanel v-else-if="!games.length" kind="empty" title="还没有匹配的游戏" message="清除筛选，或换一个分类继续探索。" /><GameGrid v-else :games="games" :favorites="favorites" @favorite="favorite" @play="play" /></div></template>
